  min-width: 0;
}

.reading-body .reading-mfa-title,
.reading-mfa-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text);
  margin: 0 !important;
  line-height: 1.3;
}

.reading-mfa-subtitle {
  font-size: 0.875rem;
  color: var(--text-dim, #94a3b8);
  font-weight: 500;
  line-height: 1.35;
}

.reading-treatment-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
  border-bottom: 1px solid var(--line);
  padding-bottom: 0.625rem;
}

.reading-concept-title-group {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.reading-treatment-title-group {
