  align-items: baseline;
  gap: 12px;
  flex: 1 1 auto;
}

.reading-precedence-num {
  font-family: 'JetBrains Mono', monospace;
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--blue);
  letter-spacing: -0.02em;
  flex-shrink: 0;
}

.reading-precedence-title {
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--text-heading);
  margin: 0;
  line-height: 1.45;
}

.reading-precedence-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  background: var(--panel-2);
  border: 1px solid var(--line);
  color: var(--text-muted);
  white-space: nowrap;
}

.reading-precedence-card.tier-1 .reading-precedence-badge {
  background: rgba(59, 130, 246, 0.1);
  border-color: rgba(59, 130, 246, 0.3);
  color: var(--blue);
}

.reading-precedence-body {
  font-size: 0.92rem;
  line-height: 1.65;
  margin: 0;
  color: var(--text);
}

.reading-precedence-body strong {
  color: var(--text-heading);
}

.reading-precedence-divider {
  display: none; /* Precedence rule is stated once at the top */
}

/* ==========================================================================
   Smart Floating Scroll Navigation
   ========================================================================== */
.reading-scroll-nav {
  position: fixed;
  bottom: 28px;
  right: 28px;
  z-index: 100;
  width: 42px;
  height: 42px;
  padding: 0;
  margin: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm, 8px);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
  cursor: pointer;
  transition: opacity 0.2s ease, visibility 0.2s ease, background-color 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}

html[data-theme="light"] .reading-scroll-nav {
  background: var(--panel);
  border-color: var(--line);
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.12);
}

.reading-scroll-nav:hover {
  background: var(--panel-2);
  border-color: var(--line-hover, var(--blue));
  color: var(--blue);
  transform: translateY(-2px);
}

.reading-scroll-nav:active {
  transform: translateY(0);
}

.reading-scroll-nav:focus-visible {
  outline: 2px solid var(--blue);
  outline-offset: 2px;
}

.reading-scroll-nav.is-hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(8px);
}

.reading-scroll-nav-icon {
  width: 20px;
  height: 20px;
  stroke: currentColor;
  stroke-width: 2.25;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
  pointer-events: none;
}

@media (max-width: 840px) {
  .reading-scroll-nav {
    bottom: 20px;
    right: 20px;
    width: 40px;
    height: 40px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .reading-scroll-nav {
    transition: none !important;
    transform: none !important;
  }
}

