/**
 * ISC2 CC 2026 — Reading Notes Screen Module
 *
 * Provides a clean technical documentation reader:
 * - Domain 1 complete real content integration (consolidated from D1 sum.md & Domain 1.md)
 * - 3-level navigation hierarchy in left sidebar: Domain -> Objective -> Topic
 * - Independent expand/collapse without scroll loss
 * - Smooth anchor scrolling to Objectives and Topics
 * - Scroll spy for active heading/section highlight
 * - Continuous long-form reading directly on page background
 * - Domains 2-5 preserved in unpublished state with quiet coming-soon note
 */

import { state } from '../core/state.js';
import { renderThemeToggle, attachThemeToggle } from './components/theme-toggle.js';
import { loadDomainReading, getDomainReadingCached } from '../core/reading-loader.js';
import { getReadingProgressStore, loadReadingProgress, saveReadingLocation, parseReadingDeepLink, resolveReadingLocation } from '../core/reading-progress.js';
import { domain1Objectives } from '../../content/isc2-cc-2026/reading/domain-1.js';
import { domain2Objectives, domain2Review } from '../../content/isc2-cc-2026/reading/domain-2.js';
import { domain3Objectives, domain3Review } from '../../content/isc2-cc-2026/reading/domain-3.js';
import { domain4Objectives, domain4Review } from '../../content/isc2-cc-2026/reading/domain-4.js';

export const READING_DOMAINS = [
  {
    id: 1,
    title: 'Domain 1: Security Principles',
    shortTitle: 'Security Principles',
    weight: '24%',
    published: true,
    objectives: domain1Objectives
  },
  {
    id: 2,
    title: 'Domain 2: Security Governance',
    shortTitle: 'Security Governance',
    weight: '17.3%',
    published: true,
    objectives: domain2Objectives,
    review: domain2Review
  },
  {
    id: 3,
    title: 'Domain 3: Identity and Access Management (IAM) Concepts',
    shortTitle: 'Access Controls',
    weight: '20%',
    published: true,
    objectives: domain3Objectives,
    review: domain3Review
  },
  {
    id: 4,
    title: 'Domain 4: Networking and Cloud Security Concepts',
    shortTitle: 'Network Security',
    weight: '21.3%',
    published: true,
    objectives: domain4Objectives,
    review: domain4Review
  },
  {
    id: 5,
    title: 'Domain 5: Security Operations',
    shortTitle: 'Security Operations',
    weight: '17.3%',
    published: false,
    objectives: [
      { id: '5.1', title: '5.1 Understand data security' },
      { id: '5.2', title: '5.2 Understand security operations' },
      { id: '5.3', title: '5.3 Understand Incident Response (IR)' },
      { id: '5.4', title: '5.4 Understand asset protection' },
      { id: '5.5', title: '5.5 Understand security testing' }
    ]
  }
];

let disposeActiveReader = null;
const initialDocumentUrl = typeof window !== 'undefined' ? window.location?.href : null;
let readerMountedInDocument = false;

function escapeHtml(value) {
  if (value === null || value === undefined) return '';
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Renders the Reading Notes screen into the provided container.
 * @param {HTMLElement} container - Root application element
 * @param {Function} onBack - Callback when user navigates back to exam versions
 */
export function renderReadingScreen(container, onBack) {
  disposeActiveReader?.();
  const allDomainObjectiveIds = READING_DOMAINS.flatMap(d => (d.objectives || []).map(o => o.id));
  const progress = loadReadingProgress();
  const initialDocumentMount = !readerMountedInDocument && window.location.href === initialDocumentUrl;
  readerMountedInDocument = true;
  const initialLocation = resolveReadingLocation({
    hash: window.location.hash, progress,
    navigationType: initialDocumentMount ? performance.getEntriesByType('navigation')[0]?.type : 'navigate',
    historyPosition: history.state?.readingNotes
  });
  // Keep the existing explicitly selected, unpublished panel outside V1 progress.
  if (!parseReadingDeepLink(window.location.hash).isReadingRoute && state.reading?.selectedDomainId === 5) {
    Object.assign(initialLocation, { domainId: 5, anchorId: null, scrollY: 0, mode: 'position' });
  }
  state.reading = state.reading || {};
  state.reading.selectedDomainId = initialLocation.domainId;
  state.reading._hasRestoredProgress = true;
  state.reading.targetAnchorId = null;
  state.reading.targetScrollY = null;
  let selectedDomainId = initialLocation.domainId;
  const expandedDomainSet = new Set(state.reading.expandedDomains || [selectedDomainId]);
  const expandedObjSet = new Set(state.reading.expandedObjectives || allDomainObjectiveIds);
  expandedDomainSet.add(selectedDomainId);

  const initialAnchor = initialLocation.anchorId;

  // Auto-expand domain and objective if initialAnchor belongs to one
  if (initialAnchor) {
    const objMatch = initialAnchor.match(/^(?:topic|obj)-(\d+)-(\d+)/);
    if (objMatch) {
      expandedDomainSet.add(parseInt(objMatch[1], 10));
      expandedObjSet.add(`${objMatch[1]}.${objMatch[2]}`);
    }
  }

  let sidebarCollapsed = !!state.reading.sidebarCollapsed;
  let mobileSidebarOpen = false;
  let scrollNavCleanup = null;
  let updateScrollNavState = null;
  let activeScrollSpyTopicId = initialAnchor;
  let scrollDebounceTimer = null;
  let restoreGeneration = 0;
  let pendingRestoration = null;
  let restoring = true;
  let disposed = false;
  let readerRoot = null;
  let headingTargets = [];
  let lastSnapshot = null;
  let removalObserver = null;
  const listeners = new AbortController();
  const previousScrollRestoration = history.state?.readingNotes?.previousScrollRestoration || history.scrollRestoration;
  history.scrollRestoration = 'manual';
  const isMounted = () => !disposed && readerRoot && container.contains(readerRoot);
  const listen = (target, type, callback, options = {}) => target?.addEventListener(type, callback, { ...options, signal: listeners.signal });

  function getCurrentScrollY() {
    const pane = container.querySelector('#reading-content-pane');
    if (pane && pane.scrollTop > 0) return pane.scrollTop;
    if (typeof window !== 'undefined' && window.scrollY > 0) return window.scrollY;
    const docEl = typeof document !== 'undefined' ? document.documentElement : null;
    return docEl ? docEl.scrollTop : 0;
  }

  function setActiveAnchor(id, expand = false) {
    activeScrollSpyTopicId = id;
    const match = id?.match(/^(?:topic|obj)-(\d+)-(\d+)/);
    const objective = match ? `${match[1]}.${match[2]}` : null;
    if (expand && objective) {
      expandedDomainSet.add(selectedDomainId);
      expandedObjSet.add(objective);
      state.reading.expandedDomains = [...expandedDomainSet];
      state.reading.expandedObjectives = [...expandedObjSet];
      const group = container.querySelector(`.reading-nav-group[data-domain-id="${selectedDomainId}"]`);
      const item = group?.querySelector(`[data-objective-id="${objective}"]`);
      for (const [owner, buttonSelector, listSelector] of [[group, '[data-toggle-domain]', '.reading-nav-sub-tree'], [item, '[data-toggle-obj]', '.reading-nav-topics']]) {
        owner?.classList.add('expanded');
        const button = owner?.querySelector(buttonSelector);
        button?.classList.add('expanded');
        button?.setAttribute('aria-expanded', 'true');
        const list = owner?.querySelector(listSelector);
        if (list) { list.hidden = false; list.classList.add('expanded'); }
      }
    }
    container.querySelectorAll('.reading-nav-topic-link, .reading-nav-objective-link').forEach(link => {
      const target = link.getAttribute('data-scroll-to');
      link.classList.toggle('active', target === id || (objective && target === `obj-${objective.replace('.', '-')}`));
      if (target === id) link.setAttribute('aria-current', 'location');
      else link.removeAttribute('aria-current');
    });
  }

  function updateActiveFromScroll() {
    let active = null;
    for (const target of headingTargets) {
      if (target.getBoundingClientRect().top <= 80) active = target.id;
      else break;
    }
    setActiveAnchor(active);
  }

  function snapshotLocation() {
    const target = activeScrollSpyTopicId && document.getElementById(activeScrollSpyTopicId);
    const match = activeScrollSpyTopicId?.match(/^(?:topic|obj)-(\d+)-(\d+)/);
    return {
      domainId: selectedDomainId, topicId: activeScrollSpyTopicId,
      objectiveId: match ? `${match[1]}.${match[2]}` : null,
      scrollY: getCurrentScrollY(),
      ...(target ? { anchorOffset: -target.getBoundingClientRect().top } : {})
    };
  }

  function writeHistory(location, method = 'replaceState', hash = null) {
    const anchor = location.topicId ?? location.anchorId;
    const route = hash || (anchor ? `#${anchor}` : `#/reading/domain-${location.domainId}`);
    history[method]({ ...(history.state || {}), readingNotes: {
      domainId: location.domainId, anchorId: anchor || null,
      scrollY: location.scrollY || 0, anchorOffset: location.anchorOffset, hash: route,
      previousScrollRestoration
    } }, '', route);
  }

  function persistCurrent(updateHistory = true) {
    if (!isMounted() || restoring || !getActiveDomain().published) return;
    updateActiveFromScroll();
    lastSnapshot = snapshotLocation();
    saveReadingLocation(lastSnapshot);
    if (updateHistory) writeHistory(lastSnapshot);
  }

  function beginRestore(location) {
    restoring = true;
    clearTimeout(scrollDebounceTimer);
    const generation = ++restoreGeneration;
    pendingRestoration = { location, generation };
    return generation;
  }

  function restorePendingLocation() {
    const request = pendingRestoration;
    if (request?.location.domainId === selectedDomainId) restoreLocation(request.location, request.generation);
  }

  async function restoreLocation(location, generation) {
    if (!isMounted() || generation !== restoreGeneration) return;
    if (!getActiveDomain().published) { restoring = false; pendingRestoration = null; return; }
    // Same-domain navigation can arrive while the article is still loading.
    // Keep its intent until the current content request supplies real targets.
    if (!getDomainReadingCached(selectedDomainId) || !container.querySelector('.reading-article-markdown')) return;
    // Wait for the actual article and font/image layout once, rather than retrying
    // scroll commands after the user has started reading or a new route has won.
    const images = [...container.querySelectorAll('.reading-article img')].map(img => img.decode?.().catch(() => {}));
    let timeout;
    await Promise.race([
      Promise.all([document.fonts?.ready, ...images]),
      new Promise(resolve => { timeout = setTimeout(resolve, 1500); })
    ]);
    clearTimeout(timeout);
    if (!isMounted() || generation !== restoreGeneration) return;
    await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
    if (!isMounted() || generation !== restoreGeneration) return;
    const target = location.anchorId && document.getElementById(location.anchorId);
    if (location.mode === 'anchor' && target) {
      target.scrollIntoView({ behavior: 'instant', block: 'start' });
    } else {
      const top = target && typeof location.anchorOffset === 'number'
        ? getCurrentScrollY() + target.getBoundingClientRect().top + location.anchorOffset
        : location.scrollY || 0;
      const pane = container.querySelector('#reading-content-pane');
      if (pane && getComputedStyle(pane).overflowY === 'auto' && pane.scrollHeight > pane.clientHeight) pane.scrollTo({ top, behavior: 'instant' });
      else window.scrollTo({ top, behavior: 'instant' });
    }
    restoring = false;
    pendingRestoration = null;
    if (target) setActiveAnchor(target.id, true);
    persistCurrent();
    updateScrollNavState?.();
  }

  function cancelDelayedRestore() {
    if (!restoring) return;
    ++restoreGeneration;
    pendingRestoration = null;
    restoring = false;
  }

  function syncSidebarState(returnFocus = false) {
    const mobile = window.innerWidth <= 840;
    const sidebar = container.querySelector('#reading-sidebar');
    const trigger = container.querySelector('#btn-toggle-sidebar');
    const visible = mobile ? mobileSidebarOpen : !sidebarCollapsed;
    if (!visible && (returnFocus || sidebar?.contains(document.activeElement))) trigger?.focus({ preventScroll: true });
    if (sidebar) {
      sidebar.inert = !visible;
      if (visible) sidebar.removeAttribute('aria-hidden');
      else sidebar.setAttribute('aria-hidden', 'true');
    }
    trigger?.setAttribute('aria-expanded', String(visible));
    container.querySelector('#reading-layout')?.classList.toggle('mobile-sidebar-open', mobile && mobileSidebarOpen);
  }

  function closeMobileSidebar(returnFocus = false) {
    mobileSidebarOpen = false;
    syncSidebarState(returnFocus);
  }

  function disposeReader() {
    if (disposed) return;
    if (isMounted()) persistCurrent(false);
    else if (!restoring && lastSnapshot) saveReadingLocation(lastSnapshot);
    disposed = true;
    ++restoreGeneration;
    clearTimeout(scrollDebounceTimer);
    scrollNavCleanup?.();
    listeners.abort();
    removalObserver?.disconnect();
    history.scrollRestoration = previousScrollRestoration;
    if (disposeActiveReader === disposeReader) disposeActiveReader = null;
  }
  disposeActiveReader = disposeReader;

  function getActiveDomain() {
    return READING_DOMAINS.find(d => d.id === selectedDomainId) || READING_DOMAINS[0];
  }

  function renderSidebarNavHtml() {
    return READING_DOMAINS.map(domain => {
      const isActive = domain.id === selectedDomainId;
      const isExpanded = expandedDomainSet.has(domain.id);
      const objectives = domain.objectives || [];

      return `
        <div class="reading-nav-group ${isActive ? 'active' : ''} ${isExpanded ? 'expanded' : ''}" data-domain-id="${domain.id}">
          <div class="reading-nav-domain-row ${isActive ? 'active' : ''}">
            <button type="button" class="reading-chevron-btn ${isExpanded ? 'expanded' : ''}" data-toggle-domain="${domain.id}" aria-label="${isExpanded ? 'Collapse' : 'Expand'} ${escapeHtml(domain.title)}" aria-expanded="${isExpanded}">
              <svg class="reading-chevron-svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <polyline points="9 18 15 12 9 6"></polyline>
              </svg>
            </button>
            <button type="button" class="reading-domain-btn ${isActive ? 'active' : ''}" data-select-domain="${domain.id}" aria-label="Select ${escapeHtml(domain.title)}">
              <span class="reading-domain-label">Domain ${domain.id}</span>
              <span class="reading-domain-title">${escapeHtml(domain.shortTitle)}</span>
            </button>
          </div>
          <div class="reading-nav-sub-tree ${isExpanded ? 'expanded' : ''}" ${isExpanded ? '' : 'hidden'}>
            <ul class="reading-nav-objectives">
              ${objectives.map(obj => {
                const hasTopics = obj.topics && obj.topics.length > 0;
                const isObjExpanded = expandedObjSet.has(obj.id);
                return `
                  <li class="reading-nav-objective-item ${isObjExpanded ? 'expanded' : ''}" data-objective-id="${escapeHtml(obj.id)}">
                    <div class="reading-nav-objective-row">
                      ${hasTopics ? `
                        <button type="button" class="reading-obj-chevron-btn ${isObjExpanded ? 'expanded' : ''}" data-toggle-obj="${escapeHtml(obj.id)}" aria-label="${isObjExpanded ? 'Collapse' : 'Expand'} topics for ${escapeHtml(obj.id)}" aria-expanded="${isObjExpanded}">
                          <svg class="reading-chevron-svg" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                            <polyline points="9 18 15 12 9 6"></polyline>
                          </svg>
                        </button>
                      ` : `
                        <span class="reading-obj-bullet"></span>
                      `}
                      ${isActive && hasTopics ? `
                        <a href="#${escapeHtml(obj.anchorId || ('obj-' + obj.id.replace('.', '-')))}" class="reading-nav-objective-link" data-scroll-to="${escapeHtml(obj.anchorId || ('obj-' + obj.id.replace('.', '-')))}">
                          <span class="reading-nav-objective-title">${escapeHtml(obj.title)}</span>
                        </a>
                      ` : `
                        <span class="reading-nav-objective-title reading-nav-objective-static">${escapeHtml(obj.title)}</span>
                      `}
                    </div>
                    ${hasTopics ? `
                      <ul class="reading-nav-topics ${isObjExpanded ? 'expanded' : ''}" ${isObjExpanded ? '' : 'hidden'}>
                        ${obj.topics.map(t => `
                          <li class="reading-nav-topic-item">
                            <a href="#${escapeHtml(t.id)}" class="reading-nav-topic-link" data-scroll-to="${escapeHtml(t.id)}">${escapeHtml(t.title)}</a>
                          </li>
                        `).join('')}
                      </ul>
                    ` : ''}
                  </li>
                `;
              }).join('')}
              ${domain.review ? `
                <li class="reading-nav-objective-item reading-nav-review-item">
                  <div class="reading-nav-objective-row">
                    <span class="reading-obj-bullet"></span>
                    ${isActive ? `
                      <a href="#${escapeHtml(domain.review.anchorId || domain.review.id)}" class="reading-nav-objective-link reading-nav-review-link" data-scroll-to="${escapeHtml(domain.review.anchorId || domain.review.id)}">
                        <span class="reading-nav-objective-title">${escapeHtml(domain.review.title)}</span>
                      </a>
                    ` : `
                      <span class="reading-nav-objective-title reading-nav-objective-static">${escapeHtml(domain.review.title)}</span>
                    `}
                  </div>
                </li>
              ` : ''}
            </ul>
          </div>
        </div>
      `;
    }).join('');
  }

  function renderArticleContent(domain) {
    if (domain.published) {
      const cached = getDomainReadingCached(domain.id);
      if (cached) {
        return `
          <article class="reading-article" data-domain-id="${domain.id}">
            <header class="reading-article-header">
              <div class="reading-eyebrow">ISC2 CC 2026 · Domain ${domain.id} · Exam Weight ${escapeHtml(domain.weight)}</div>
              <h1 class="reading-article-title">${escapeHtml(domain.title)}</h1>
            </header>
            <div class="reading-body reading-article-markdown">
              ${cached.renderedHtml}
            </div>
          </article>
        `;
      }
      return `
        <article class="reading-article" data-domain-id="${domain.id}">
          <header class="reading-article-header">
            <div class="reading-eyebrow">ISC2 CC 2026 · Domain ${domain.id} · Exam Weight ${escapeHtml(domain.weight)}</div>
            <h1 class="reading-article-title">${escapeHtml(domain.title)}</h1>
          </header>
          <div class="reading-body reading-article-markdown">
            <div class="reading-unpublished-note">
              <p class="reading-unpublished-text">Loading Domain ${domain.id} reading notes...</p>
            </div>
          </div>
        </article>
      `;
    }

    // Unpublished Domains (3-5)
    return `
      <article class="reading-article" data-domain-id="${domain.id}">
        <header class="reading-article-header">
          <div class="reading-eyebrow">ISC2 CC 2026 · Domain ${domain.id} · Exam Weight ${escapeHtml(domain.weight)}</div>
          <h1 class="reading-article-title">${escapeHtml(domain.title)}</h1>
        </header>

        <div class="reading-body">
          <div class="reading-unpublished-note">
            <p class="reading-unpublished-text">Reading content coming soon.</p>
          </div>
        </div>
      </article>
    `;
  }

  function renderFullView() {
    beginRestore(initialLocation);
    const activeDomain = getActiveDomain();
    const articleHtml = renderArticleContent(activeDomain);

    container.innerHTML = `
      <div class="reading-screen">
        <header class="reading-top-bar">
          <div class="reading-top-left">
            <button type="button" class="btn btn-secondary btn-back-home" id="btn-reading-back">← Back to Exam Versions</button>
            <button type="button" class="btn btn-secondary btn-toggle-sidebar" id="btn-toggle-sidebar" aria-label="Toggle navigation sidebar" title="Toggle Sidebar" aria-controls="reading-sidebar" aria-expanded="false">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
                <line x1="9" y1="3" x2="9" y2="21"></line>
              </svg>
              <span class="btn-toggle-label">Sidebar</span>
            </button>
          </div>
          <div class="reading-top-center">
            <span class="reading-app-badge">ISC2 CC 2026 — Reading Notes</span>
          </div>
          <div class="reading-top-actions">
            ${renderThemeToggle('reading-theme-toggle')}
          </div>
        </header>

        <div class="reading-layout ${sidebarCollapsed ? 'sidebar-collapsed' : ''} ${mobileSidebarOpen ? 'mobile-sidebar-open' : ''}" id="reading-layout">
          <div class="reading-backdrop" id="reading-backdrop" aria-hidden="true"></div>

          <aside class="reading-sidebar" id="reading-sidebar" aria-label="Domain Navigation">
            <div class="reading-sidebar-header">
              <span class="reading-sidebar-title">Domains & Objectives</span>
              <button type="button" class="reading-sidebar-close-mobile" id="btn-sidebar-close-mobile" aria-label="Close navigation sidebar">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                  <line x1="18" y1="6" x2="6" y2="18"></line>
                  <line x1="6" y1="6" x2="18" y2="18"></line>
                </svg>
              </button>
            </div>
            <nav class="reading-nav-domains" id="reading-nav-domains">
              ${renderSidebarNavHtml()}
            </nav>
          </aside>

          <main class="reading-content-pane" id="reading-content-pane" tabindex="-1">
            ${articleHtml}
          </main>
        </div>

        <button type="button" class="reading-scroll-nav is-hidden" id="btn-reading-scroll-nav" aria-label="Go to bottom" title="Go to bottom">
          <svg class="reading-scroll-nav-icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <line x1="12" y1="5" x2="12" y2="19"></line>
            <polyline points="19 12 12 19 5 12"></polyline>
          </svg>
        </button>
      </div>
    `;

    readerRoot = container.querySelector('.reading-screen');
    attachThemeToggle(container, 'reading-theme-toggle');
    bindEvents();
    syncSidebarState();
    setupScrollSpy();
    initScrollNavigation();

    if (activeDomain.published && !getDomainReadingCached(activeDomain.id)) {
      loadDomainReading(activeDomain.id).then(() => {
        if (isMounted() && selectedDomainId === activeDomain.id) {
          const pane = container.querySelector('#reading-content-pane');
          if (pane) {
            pane.innerHTML = renderArticleContent(activeDomain);
          }
          setupScrollSpy();
          if (updateScrollNavState) updateScrollNavState();
          restorePendingLocation();
        }
      }).catch(err => {
        console.error(`Failed to load Domain ${activeDomain.id} notes:`, err);
      });
    } else {
      restorePendingLocation();
    }
  }

  function updateContentOnly(location) {
    beginRestore(location);
    const activeDomain = getActiveDomain();
    const pane = container.querySelector('#reading-content-pane');
    if (pane) {
      pane.innerHTML = renderArticleContent(activeDomain);
      pane.scrollTop = 0;
    }
    const nav = container.querySelector('#reading-nav-domains');
    if (nav) {
      nav.innerHTML = renderSidebarNavHtml();
      bindNavEvents();
    }
    setupScrollSpy();
    if (updateScrollNavState) updateScrollNavState();

    if (activeDomain.published && !getDomainReadingCached(activeDomain.id)) {
      loadDomainReading(activeDomain.id).then(() => {
        if (isMounted() && selectedDomainId === activeDomain.id) {
          const freshPane = container.querySelector('#reading-content-pane');
          if (freshPane) {
            freshPane.innerHTML = renderArticleContent(activeDomain);
          }
          setupScrollSpy();
          if (updateScrollNavState) updateScrollNavState();
          restorePendingLocation();
        }
      }).catch(err => {
        console.error(`Failed to load Domain ${activeDomain.id} notes:`, err);
      });
    } else {
      restorePendingLocation();
    }
  }

  function applyReadingLanguageMetadata() {
    const article = container.querySelector('.reading-article');
    if (!article || ![1, 2, 3, 4].includes(getActiveDomain().id)) return;
    article.querySelector('.reading-article-markdown')?.setAttribute('lang', 'th');
    for (const element of article.querySelectorAll('h1,h2,h3,h4,h5,h6,p,li,dt,dd,figcaption,blockquote,em,.reading-diagram-tag')) {
      const text = element.textContent;
      if (/[A-Za-z]/.test(text) && !/[\u0e00-\u0e7f]/.test(text) && !element.closest('svg,.katex,code')) element.setAttribute('lang', 'en');
    }
  }

  function setupScrollSpy() {
    applyReadingLanguageMetadata();
    // Observe real subsection headings, not the large containing objectives.
    const domain = getActiveDomain();
    const ids = (domain.objectives || []).flatMap(obj => [obj.anchorId, ...(obj.topics || []).map(topic => topic.id)]);
    if (domain.review) ids.push(domain.review.anchorId || domain.review.id);
    headingTargets = ids.map(id => document.getElementById(id)).filter(Boolean);
    if (!restoring) updateActiveFromScroll();
  }

  function navigateTo(location, push = true) {
    persistCurrent();
    clearTimeout(scrollDebounceTimer);
    const changedDomain = selectedDomainId !== location.domainId;
    selectedDomainId = location.domainId;
    state.reading.selectedDomainId = selectedDomainId;
    expandedDomainSet.add(selectedDomainId);
    state.reading.expandedDomains = [...expandedDomainSet];
    activeScrollSpyTopicId = location.anchorId;
    if (push) writeHistory(location, 'pushState');
    closeMobileSidebar();
    if (changedDomain) updateContentOnly(location);
    else restoreLocation(location, beginRestore(location));
    setActiveAnchor(location.anchorId, true);
    container.querySelector('#reading-content-pane')?.focus({ preventScroll: true });
  }

  function bindNavEvents() {
    container.querySelectorAll('[data-select-domain]').forEach(btn => {
      btn.addEventListener('click', e => {
        e.stopPropagation();
        const domainId = Number(btn.getAttribute('data-select-domain'));
        if (domainId === selectedDomainId) return;
        if (domainId === 5) {
          // Preserve the existing unpublished panel without recording Domain 5 progress.
          navigateTo({ domainId, mode: 'position', anchorId: null, scrollY: 0 });
          return;
        }
        const location = resolveReadingLocation({ hash: `#/reading/domain-${domainId}`, progress: loadReadingProgress() });
        navigateTo(location);
      });
    });

    // Toggle domain chevron independently without scroll/screen reset
    container.querySelectorAll('[data-toggle-domain]').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const dId = parseInt(btn.getAttribute('data-toggle-domain'), 10);
        const group = container.querySelector(`.reading-nav-group[data-domain-id="${dId}"]`);
        const subTree = group?.querySelector('.reading-nav-sub-tree');

        if (expandedDomainSet.has(dId)) {
          expandedDomainSet.delete(dId);
          btn.classList.remove('expanded');
          btn.setAttribute('aria-expanded', 'false');
          group?.classList.remove('expanded');
          if (subTree) {
            subTree.classList.remove('expanded');
            subTree.hidden = true;
          }
        } else {
          expandedDomainSet.add(dId);
          btn.classList.add('expanded');
          btn.setAttribute('aria-expanded', 'true');
          group?.classList.add('expanded');
          if (subTree) {
            subTree.classList.add('expanded');
            subTree.hidden = false;
          }
        }
        state.reading.expandedDomains = Array.from(expandedDomainSet);
      });
    });

    // Toggle objective chevron independently without scroll/screen reset
    container.querySelectorAll('[data-toggle-obj]').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const objId = btn.getAttribute('data-toggle-obj');
        const item = container.querySelector(`.reading-nav-objective-item[data-objective-id="${objId}"]`);
        const topicsList = item?.querySelector('.reading-nav-topics');

        if (expandedObjSet.has(objId)) {
          expandedObjSet.delete(objId);
          btn.classList.remove('expanded');
          btn.setAttribute('aria-expanded', 'false');
          item?.classList.remove('expanded');
          if (topicsList) {
            topicsList.classList.remove('expanded');
            topicsList.hidden = true;
          }
        } else {
          expandedObjSet.add(objId);
          btn.classList.add('expanded');
          btn.setAttribute('aria-expanded', 'true');
          item?.classList.add('expanded');
          if (topicsList) {
            topicsList.classList.add('expanded');
            topicsList.hidden = false;
          }
        }
        state.reading.expandedObjectives = Array.from(expandedObjSet);
      });
    });

    // Explicit subsection navigation starts at the target, even if it was read before.
    container.querySelectorAll('[data-scroll-to]').forEach(link => {
      link.addEventListener('click', e => {
        const anchorId = link.getAttribute('data-scroll-to');
        const route = parseReadingDeepLink(`#${anchorId}`);
        if (!route.domainId) return;
        e.preventDefault();
        navigateTo({ domainId: route.domainId, mode: 'anchor', anchorId, scrollY: 0 });
      });
    });
  }

  function bindEvents() {
    container.querySelector('#btn-reading-back')?.addEventListener('click', () => {
      persistCurrent();
      disposeReader();
      history.pushState(null, '', window.location.pathname + window.location.search);
      onBack();
    });
    container.querySelector('#btn-toggle-sidebar')?.addEventListener('click', () => {
      if (window.innerWidth <= 840) {
        mobileSidebarOpen = !mobileSidebarOpen;
        syncSidebarState();
        if (mobileSidebarOpen) container.querySelector('#btn-sidebar-close-mobile')?.focus({ preventScroll: true });
      } else {
        sidebarCollapsed = !sidebarCollapsed;
        state.reading.sidebarCollapsed = sidebarCollapsed;
        container.querySelector('#reading-layout')?.classList.toggle('sidebar-collapsed', sidebarCollapsed);
        syncSidebarState();
      }
    });
    container.querySelector('#btn-sidebar-close-mobile')?.addEventListener('click', () => closeMobileSidebar(true));
    container.querySelector('#reading-backdrop')?.addEventListener('click', () => closeMobileSidebar(true));
    listen(window, 'keydown', event => {
      if (event.key === 'Escape' && mobileSidebarOpen) {
        event.preventDefault();
        closeMobileSidebar(true);
      } else if (['ArrowUp', 'ArrowDown', 'PageUp', 'PageDown', 'Home', 'End', ' '].includes(event.key)) {
        cancelDelayedRestore();
      }
    });
    listen(window, 'wheel', cancelDelayedRestore, { passive: true });
    listen(window, 'touchstart', event => {
      if (!container.querySelector('#reading-sidebar')?.contains(event.target)) cancelDelayedRestore();
    }, { passive: true });
    listen(window, 'pointerdown', event => {
      if (event.target === document.documentElement || container.querySelector('#reading-content-pane')?.contains(event.target)) cancelDelayedRestore();
    });
    listen(window, 'resize', () => {
      if (window.innerWidth > 840) mobileSidebarOpen = false;
      syncSidebarState();
    }, { passive: true });
    listen(container.querySelector('#reading-sidebar'), 'focusout', event => {
      if (mobileSidebarOpen && !event.currentTarget.contains(event.relatedTarget)) closeMobileSidebar();
    });
    listen(window, 'pagehide', () => {
      persistCurrent();
      history.scrollRestoration = previousScrollRestoration;
    });
    listen(window, 'pageshow', () => { history.scrollRestoration = 'manual'; });
    listen(document, 'visibilitychange', () => { if (document.hidden) persistCurrent(); });

    const restoreRoute = () => {
      if (!isMounted()) return;
      const route = parseReadingDeepLink(location.hash);
      if (!route.isReadingRoute) return;
      const destination = resolveReadingLocation({ hash: location.hash, progress: loadReadingProgress(), historyPosition: history.state?.readingNotes });
      if (destination.domainId !== selectedDomainId) return; // Existing router owns cross-domain mounts.
      restoreLocation(destination, beginRestore(destination));
    };
    listen(window, 'hashchange', restoreRoute);
    listen(window, 'popstate', () => {
      clearTimeout(scrollDebounceTimer);
      if (!restoring && lastSnapshot) saveReadingLocation(lastSnapshot);
      cancelDelayedRestore();
      // hashchange follows popstate; this also handles same-hash history entries.
      queueMicrotask(restoreRoute);
    });
    bindNavEvents();
  }

  function initScrollNavigation() {
    if (scrollNavCleanup) {
      scrollNavCleanup();
      scrollNavCleanup = null;
    }

    const scrollNavBtn = container.querySelector('#btn-reading-scroll-nav');
    if (!scrollNavBtn) return;

    const SCROLL_THRESHOLD = 30; // 30px threshold to prevent jitter

    function getScrollTargetInfo() {
      const pane = container.querySelector('#reading-content-pane');
      const isPaneScroll = pane && typeof window !== 'undefined' && typeof window.getComputedStyle === 'function' && window.getComputedStyle(pane).overflowY === 'auto' && pane.scrollHeight > pane.clientHeight;
      if (isPaneScroll) {
        return {
          element: pane,
          isWindow: false,
          getScrollTop: () => pane.scrollTop,
          getScrollHeight: () => pane.scrollHeight,
          getClientHeight: () => pane.clientHeight,
          scrollTo: (top, behavior) => pane.scrollTo({ top, behavior })
        };
      }
      const docEl = typeof document !== 'undefined' ? document.documentElement : null;
      return {
        element: typeof window !== 'undefined' ? window : null,
        isWindow: true,
        getScrollTop: () => (typeof window !== 'undefined' ? window.scrollY : 0) || (docEl ? docEl.scrollTop : 0) || 0,
        getScrollHeight: () => Math.max(docEl ? docEl.scrollHeight : 0, (typeof document !== 'undefined' && document.body) ? document.body.scrollHeight : 0),
        getClientHeight: () => (typeof window !== 'undefined' ? window.innerHeight : 0) || (docEl ? docEl.clientHeight : 0) || 0,
        scrollTo: (top, behavior) => {
          if (typeof window !== 'undefined') window.scrollTo({ top, behavior });
        }
      };
    }

    let currentState = null; // 'bottom' | 'top' | 'hidden'

    function updateNav() {
      const targetInfo = getScrollTargetInfo();
      const scrollHeight = targetInfo.getScrollHeight();
      const clientHeight = targetInfo.getClientHeight();
      const scrollTop = targetInfo.getScrollTop();

      const article = container.querySelector('.reading-article');
      const articleHeight = article ? (article.scrollHeight || article.offsetHeight) : 0;
      const articleOverflows = article ? (articleHeight > (clientHeight - 60)) : ((scrollHeight - clientHeight) > SCROLL_THRESHOLD);
      const canScroll = articleOverflows && ((scrollHeight - clientHeight) > SCROLL_THRESHOLD);

      if (!canScroll) {
        if (currentState !== 'hidden') {
          currentState = 'hidden';
          scrollNavBtn.classList.add('is-hidden');
          scrollNavBtn.setAttribute('aria-hidden', 'true');
          scrollNavBtn.tabIndex = -1;
        }
        return;
      }

      scrollNavBtn.classList.remove('is-hidden');
      scrollNavBtn.removeAttribute('aria-hidden');
      scrollNavBtn.tabIndex = 0;

      const isAtTop = scrollTop <= SCROLL_THRESHOLD;
      const newState = isAtTop ? 'bottom' : 'top';

      if (currentState !== newState) {
        currentState = newState;
        if (newState === 'bottom') {
          // State 1: At top -> Downward arrow -> Go to bottom
          scrollNavBtn.innerHTML = `
            <svg class="reading-scroll-nav-icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <line x1="12" y1="5" x2="12" y2="19"></line>
              <polyline points="19 12 12 19 5 12"></polyline>
            </svg>
          `;
          scrollNavBtn.setAttribute('aria-label', 'Go to bottom');
          scrollNavBtn.setAttribute('title', 'Go to bottom');
        } else {
          // State 2: Scrolled away -> Upward arrow -> Back to top
          scrollNavBtn.innerHTML = `
            <svg class="reading-scroll-nav-icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <line x1="12" y1="19" x2="12" y2="5"></line>
              <polyline points="5 12 12 5 19 12"></polyline>
            </svg>
          `;
          scrollNavBtn.setAttribute('aria-label', 'Back to top');
          scrollNavBtn.setAttribute('title', 'Back to top');
        }
      }
    }

    updateScrollNavState = updateNav;

    function handleClick(e) {
      e.preventDefault();
      const targetInfo = getScrollTargetInfo();
      const prefersReducedMotion = typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const behavior = prefersReducedMotion ? 'auto' : 'smooth';

      if (currentState === 'bottom') {
        targetInfo.scrollTo(targetInfo.getScrollHeight(), behavior);
      } else if (currentState === 'top') {
        targetInfo.scrollTo(0, behavior);
      }
    }

    scrollNavBtn.addEventListener('click', handleClick);

    let ticking = false;
    function onScroll() {
      if (!ticking) {
        if (typeof window !== 'undefined' && window.requestAnimationFrame) {
          window.requestAnimationFrame(() => {
            updateNav();
            ticking = false;
          });
        } else {
          updateNav();
          ticking = false;
        }
        ticking = true;
      }

      if (!isMounted() || restoring) return;
      updateActiveFromScroll();
      lastSnapshot = snapshotLocation();
      // History positions are per entry; passive scrolling must not add entries.
      writeHistory(lastSnapshot);
      clearTimeout(scrollDebounceTimer);
      scrollDebounceTimer = setTimeout(() => persistCurrent(), 300);
    }

    const currentTarget = getScrollTargetInfo();
    const eventTarget = currentTarget.isWindow ? (typeof window !== 'undefined' ? window : null) : currentTarget.element;
    if (eventTarget) {
      eventTarget.addEventListener('scroll', onScroll, { passive: true });
    }
    if (typeof window !== 'undefined') {
      window.addEventListener('resize', onScroll, { passive: true });
    }

    let resizeObserver = null;
    const contentPane = container.querySelector('#reading-content-pane');
    if (typeof ResizeObserver !== 'undefined' && contentPane) {
      resizeObserver = new ResizeObserver(() => {
        updateNav();
      });
      resizeObserver.observe(contentPane);
    }

    // Initial evaluation
    updateNav();

    scrollNavCleanup = () => {
      if (scrollDebounceTimer) clearTimeout(scrollDebounceTimer);
      scrollNavBtn.removeEventListener('click', handleClick);
      if (eventTarget) {
        eventTarget.removeEventListener('scroll', onScroll);
      }
      if (typeof window !== 'undefined') {
        window.removeEventListener('resize', onScroll);
      }
      if (resizeObserver) {
        resizeObserver.disconnect();
        resizeObserver = null;
      }
      updateScrollNavState = null;
    };
  }

  renderFullView();
  if (!parseReadingDeepLink(window.location.hash).isReadingRoute) writeHistory(initialLocation, 'pushState');
  removalObserver = new MutationObserver(() => { if (!isMounted()) disposeReader(); });
  removalObserver.observe(container, { childList: true });
  return { dispose: disposeReader };
}

